enum ProfileRole { customer, provider }
enum ProfileStatus { incomplete, complete }
class CustomerProfile { final String userId,fullName,addressLine,city,area; final double latitude,longitude; final String? photoPath; const CustomerProfile({required this.userId,required this.fullName,required this.addressLine,required this.city,required this.area,required this.latitude,required this.longitude,this.photoPath}); }
class ProviderProfile { final String userId,fullName,cnicNumber,area,city; final double latitude,longitude; final int yearsExperience; final String? shopLocation,photoPath,cnicFrontPath,cnicBackPath; const ProviderProfile({required this.userId,required this.fullName,required this.cnicNumber,required this.area,required this.city,required this.latitude,required this.longitude,required this.yearsExperience,this.shopLocation,this.photoPath,this.cnicFrontPath,this.cnicBackPath}); }
class CustomerProfileDraft { final String fullName,addressLine,city,area; final double latitude,longitude; final String? photoPath; const CustomerProfileDraft({required this.fullName,required this.addressLine,required this.city,required this.area,required this.latitude,required this.longitude,this.photoPath}); }
class ProviderProfileDraft { final String fullName,cnicNumber,area,city; final double latitude,longitude; final int yearsExperience; final String? shopLocation,photoPath,cnicFrontPath,cnicBackPath; const ProviderProfileDraft({required this.fullName,required this.cnicNumber,required this.area,required this.city,required this.latitude,required this.longitude,required this.yearsExperience,this.shopLocation,this.photoPath,this.cnicFrontPath,this.cnicBackPath}); }
